materials.vertexShader:
varying vec3 vDir;
void main(){
  vDir = normalize(position);
  vec4 p = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  gl_Position = p.xyww; /* at the far plane */
}

materials.fragmentShader:
varying vec3 vDir;
uniform float uExposure;

uniform vec3 uSunDir, uZenith, uHorizon, uGround, uSunColor, uCloudLit, uCloudShade, uGlow;
uniform float uTime, uSunSize, uSunPower, uGradPow, uHaze;
uniform float uCover, uCloudAlt, uCloudScale, uCloudSoft, uCloudDark, uCloudLayerHigh, uCloudBase, uCloudVert;
uniform float uStars, uAurora, uAuroraSeed, uAuroraStyle, uMoon, uRainbow, uSunRays, uCityGlow;
uniform vec3 uMoonDir, uCityColor;
uniform vec3 uAuroraLow, uAuroraMid, uAuroraTop;

float skyHash(vec3 p){ p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float skyHash2(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }   // sin-free: sin() hashes band and block on real GPUs
float skyNoise(vec2 p){
  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(skyHash2(i), skyHash2(i + vec2(1, 0)), f.x), mix(skyHash2(i + vec2(0, 1)), skyHash2(i + vec2(1, 1)), f.x), f.y);
}
float skyFbm(vec2 p){ float a = 0.5, s = 0.0; for (int i = 0; i < 5; i++) { s += a * skyNoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; } return s; }

/* cellular puffs: round blobs of random size per cell, so clouds read as separate cumulus with gaps between them */
float skyCell(vec2 p){
  vec2 i = floor(p), f = fract(p); float m = 0.0;
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 g = vec2(float(x), float(y));
    vec2 o = vec2(skyHash2(i + g), skyHash2(i + g + 17.3));
    float r = 0.30 + 0.34 * skyHash2(i + g + 3.1);
    float dd = length(g + o - f) / r;
    m = max(m, smoothstep(1.0, 0.25, dd) * (0.55 + 0.45 * skyHash2(i + g + 9.0)));
  }
  return m;
}
/* cumulus layer: density on a plane at altitude uCloudAlt */
float cloudDensity(vec2 p){
  float big = skyCell(p * 0.5);
  float mid = skyCell(p * 1.1 + 4.2);
  float small = skyCell(p * 2.6 + 8.7);
  float d = (big * 0.62 + mid * 0.42) * (0.75 + 0.55 * small) * (0.6 + 0.8 * skyFbm(p * 1.7));   // lumpy union of bumps, ragged edge
  float thr = 0.62 - 0.4 * uCover;
  return smoothstep(thr, thr + uCloudSoft, d);
}

vec3 skyColor(vec3 d){
  float sunUp = smoothstep(-0.12, 0.08, uSunDir.y);       // 0 at night, 1 by day
  float h = d.y;
  float sd = max(dot(d, uSunDir), 0.0);

  /* gradient: ground haze below the horizon, horizon band, then zenith */
  vec3 col = mix(uHorizon, uZenith, pow(clamp(h, 0.0, 1.0), uGradPow));
  col = mix(col, uGround, smoothstep(0.0, -0.35, h));
  /* warm scattering toward the sun, a broad one and a tight one */
  col += uGlow * (pow(sd, 6.0) * 0.10 + pow(sd, 40.0) * 0.45) * (1.0 - clamp(h * 1.4, 0.0, 0.7));
  /* sun disc with a soft edge and a bright core */
  float disc = smoothstep(uSunSize, uSunSize * 0.82, 1.0 - sd);
  col += uSunColor * (disc * uSunPower + pow(sd, 900.0) * uSunPower * 0.6);

  /* stars: fixed cells, steady brightness (no twinkle) */
  if (uStars > 0.0 && h > 0.0) {
    vec3 q = d * 260.0; vec3 c = floor(q); float r = skyHash(c);
    float star = step(0.9965, r) * smoothstep(0.32, 0.0, length(fract(q) - 0.5)) * (0.45 + 0.4 * skyHash(c + 7.0));
    col += vec3(0.9, 0.95, 1.0) * star * uStars * (1.0 - sunUp) * smoothstep(0.0, 0.15, h);
  }

  /* aurora (Lux / Photon style): style 0 stacked curtains, 1 folded ribbons, 2 vertical ray corona */
  if (uAurora > 0.001 && h > 0.04) {
    vec3 a = vec3(0.0);
    float az0 = atan(d.x, -d.z);
    if (uAuroraStyle < 1.5) {
      for (int i = 0; i < 10; i++) {
        float fi = float(i) / 9.0;
        float alt = mix(2.2, 5.5, fi);
        float t = alt / h;
        vec2 p = d.xz * t * 0.16 + vec2(uAuroraSeed, uTime * 0.012);
        if (uAuroraStyle > 0.5) p.x += sin(p.y * 2.3 + uTime * 0.05 + fi * 3.0) * 0.55;   // folds
        float ridge = 1.0 - abs(2.0 * skyFbm(vec2(p.x * 0.9, p.y * 0.35)) - 1.0);
        float curtain = pow(ridge, mix(5.0, 9.0, step(0.5, uAuroraStyle))) * smoothstep(0.0, 0.35, skyFbm(p * 0.5 + 9.0));
        vec3 c = mix(uAuroraLow, mix(uAuroraMid, uAuroraTop, smoothstep(0.45, 1.0, fi)), smoothstep(0.0, 0.55, fi));
        a += c * curtain * (0.35 + 0.65 * (1.0 - fi)) / 10.0;
      }
    } else {
      float arc = smoothstep(0.55, 0.0, abs(h - 0.42 - 0.12 * skyNoise(vec2(az0 * 2.0 + uAuroraSeed, uTime * 0.01))));
      float rays = pow(skyNoise(vec2(az0 * 38.0 + uAuroraSeed, uTime * 0.03)), 2.0) * (0.6 + 0.8 * skyNoise(vec2(az0 * 5.0, 3.0)));
      float up = smoothstep(0.04, 0.2, h) * (1.0 - smoothstep(0.3, 0.95, h));
      vec3 c = mix(uAuroraLow, uAuroraTop, smoothstep(0.1, 0.8, h));
      a += c * rays * arc * up * 0.9 + uAuroraMid * arc * up * 0.12;
    }
    col += a * uAurora * 3.0 * (1.0 - sunUp) * smoothstep(0.04, 0.3, h);
  }

  /* moon: disc and halo */
  if (uMoon > 0.0) {
    float md = max(dot(d, uMoonDir), 0.0);
    col += vec3(0.85, 0.9, 1.0) * (smoothstep(0.00042, 0.00028, 1.0 - md) * 2.2 + pow(md, 300.0) * 0.5 + pow(md, 24.0) * 0.07) * uMoon;
  }

  /* rainbow opposite the sun: 40 to 43 degrees from the antisolar point, only while the sun is up and the sky is clear */
  if (uRainbow > 0.0 && sunUp > 0.1 && h > 0.0) {
    float ang = acos(clamp(dot(d, -uSunDir), -1.0, 1.0));
    float t = (ang - 0.70) / 0.075;
    if (t > 0.0 && t < 1.0) {
      vec3 rb = clamp(abs(mod(t * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
      col = mix(col, col + rb * 0.7, uRainbow * sin(t * 3.14159) * sunUp * smoothstep(0.0, 0.1, h));
    }
  }

  /* crepuscular rays: angular streaks around the sun, strongest when the sun is low */
  if (uSunRays > 0.0 && sunUp > 0.0) {
    vec3 sr = normalize(cross(uSunDir, vec3(0.0, 1.0, 0.0001))), su = cross(sr, uSunDir);
    float ang = atan(dot(d, su), dot(d, sr));
    float streak = skyNoise(vec2(ang * 7.0, uTime * 0.01)) * 0.6 + skyNoise(vec2(ang * 19.0, 4.0)) * 0.4;
    col += uGlow * pow(sd, 3.0) * streak * uSunRays * (1.0 - clamp(uSunDir.y * 1.5, 0.0, 0.8));
  }

  /* city glow hugging the horizon on the far side */
  col += uCityColor * uCityGlow * pow(1.0 - clamp(h * 3.0, 0.0, 1.0), 3.0) * (1.0 - sunUp);

  /* cumulus + high cirrus.  Low in the sky the clouds are mapped on a cylinder (azimuth, elevation) so they keep their
     height as tall towers; overhead they are mapped on a plane.  The two blend between 16 and 30 degrees.  A flat
     base cuts every cloud at constant elevation (the look of Complementary's cumulus). */
  if (h > 0.01 && uCover > 0.0) {
    float az = atan(d.x, -d.z);
    float sunAz = atan(uSunDir.x, -uSunDir.z);
    float wP = smoothstep(0.28, 0.5, h), wC = 1.0 - wP;
    vec2 drift = vec2(uTime * 0.004, uTime * 0.0015);
    float dens = 0.0, shC = 0.0, shP = 0.0;
    if (wC > 0.001) {
      vec2 p = vec2(az * 4.0, h * uCloudVert) * uCloudScale * 2.2 + drift;
      float dA = sunAz - az; dA = dA - 6.2831853 * floor((dA + 3.1415927) / 6.2831853);
      vec2 ts = normalize(vec2(dA * 2.0, (uSunDir.y - h) * 4.0 + 0.0001)) * 0.2;
      float dc = cloudDensity(p);
      if (dc > 0.002) shC = cloudDensity(p + ts) * 0.4 + cloudDensity(p + ts * 2.6) * 0.35 + cloudDensity(p + ts * 5.5) * 0.25;
      dens += dc * wC;
    }
    if (wP > 0.001) {
      float t = uCloudAlt / (h + 0.22);
      vec2 p = d.xz * t * uCloudScale + drift;
      vec2 toSun = normalize(uSunDir.xz + 1e-4) * 0.16;
      float dp = cloudDensity(p);
      if (dp > 0.002) shP = cloudDensity(p + toSun) * 0.4 + cloudDensity(p + toSun * 2.6) * 0.35 + cloudDensity(p + toSun * 5.5) * 0.25;
      dens += dp * wP;
    }
    dens *= smoothstep(uCloudBase, uCloudBase + 0.05, h);
    if (dens > 0.002) {
      float sh = shC * wC + shP * wP;
      float lit = smoothstep(0.0, 1.0, clamp(1.0 - sh * uCloudDark, 0.0, 1.0));
      vec3 body = mix(uCloudShade, uCloudLit, lit);
      float edge = clamp(1.0 - dens * 1.6, 0.0, 1.0);                  // thin edges catch the sun
      body += uSunColor * pow(sd, 8.0) * edge * 0.25 * lit;
      body *= mix(0.35, 1.0, sunUp);                                    // night clouds are dim
      float fade = smoothstep(0.0, 0.2, h);                             // melt into the horizon haze
      col = mix(col, mix(body, uHorizon, uHaze * (1.0 - fade)), dens * fade);
    }
    if (uCloudLayerHigh > 0.0) {
      float t2 = (uCloudAlt * 2.6) / h;
      vec2 q = d.xz * t2 * uCloudScale * vec2(0.5, 1.8) + vec2(uTime * 0.002, 4.0);
      float ci = smoothstep(0.58, 0.95, skyFbm(q * 1.4)) * smoothstep(0.02, 0.25, h);
      col = mix(col, mix(uCloudLit, uGlow, 0.35 * pow(sd, 3.0)), ci * uCloudLayerHigh * (0.4 + 0.6 * sunUp));
    }
  }
  return col;
}

void main(){
  gl_FragColor = vec4(skyColor(normalize(vDir)) * uExposure, 1.0);
}

materials.vertexShader:
attribute float aPhase; attribute vec2 aSeed;
uniform float uTime, uHeight, uSpread, uSize, uSpeed; uniform vec3 uPos; uniform vec2 uWind;
varying vec2 vUv; varying float vAge; varying vec2 vSeed; varying float vDepth;
void main(){
  float age = fract(uTime * uSpeed + aPhase);
  vAge = age; vSeed = aSeed; vUv = uv;
  vec3 c = uPos;
  c.y += age * uHeight;
  c.xz += uWind * age * age * uHeight * 0.5;
  float ang = aSeed.x * 6.2831 + uTime * 0.15 * (aSeed.y - 0.5);
  c.xz += vec2(cos(ang), sin(ang)) * uSpread * age * (0.3 + aSeed.y);
  float sz = uSize * (0.35 + age * 2.4) * (0.7 + 0.6 * aSeed.y);
  vec4 mv = viewMatrix * vec4(c, 1.0);
  mv.xy += position.xy * sz;
  vDepth = -mv.z;
  gl_Position = projectionMatrix * mv;
}

materials.fragmentShader:
    uniform vec3 uColor, uTop, uGlowColor; uniform float uOpacity, uGlow, uTime, uDecay, uEdge, uNear;
    varying vec2 vUv; varying float vAge; varying vec2 vSeed; varying float vDepth;

float h21(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(h21(i), h21(i + vec2(1, 0)), f.x), mix(h21(i + vec2(0, 1)), h21(i + vec2(1, 1)), f.x), f.y); }
float fbm(vec2 p){ float a = 0.5, s = 0.0; for (int i = 0; i < 4; i++) { s += a * vn(p); p = p * 2.03 + 11.7; a *= 0.5; } return s; }

    void main(){
      vec2 p = vUv - 0.5;
      float r = length(p) * 2.0;
      float n = fbm(p * 3.2 + vSeed * 17.0 + vec2(0.0, -uTime * 0.05));
      float blob = smoothstep(1.0, 0.15, r + (n - 0.5) * uEdge);
      float life = smoothstep(0.0, 0.08, vAge) * pow(1.0 - vAge, uDecay);
      float a = blob * life * uOpacity;
      if (uNear > 0.0) a *= smoothstep(uNear * 0.35, uNear, vDepth);
      vec3 col = mix(uColor, uTop, smoothstep(0.0, 0.8, vAge));
      col = mix(col, uGlowColor, uGlow * (1.0 - smoothstep(0.0, 0.3, vAge)) * 0.8);
      col *= 0.75 + 0.35 * n;
      gl_FragColor = vec4(col, a);
    }

