float skyCell(vec2 p){
  vec2 i = floor(p), f = fract(p); float m = 0.0;
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 g = vec2(float(x), float(y));
    vec2 o = vec2(skyHash2(i + g), skyHash2(i + g + 17.3));
    float r = 0.30 + 0.34 * skyHash2(i + g + 3.1);
    float dd = length(g + o - f) / r;
    m = max(m, smoothstep(1.0, 0.25, dd) * (0.55 + 0.45 * skyHash2(i + g + 9.0)));
