  float small = skyCell(p * 2.6 + 8.7);
  float d = (big * 0.62 + mid * 0.42) * (0.75 + 0.55 * small) * (0.6 + 0.8 * skyFbm(p * 1.7));   // lumpy union of bumps, ragged edge
  float thr = 0.62 - 0.4 * uCover;
  return smoothstep(thr, thr + uCloudSoft, d);
