    float streak = skyNoise(vec2(ang * 7.0, uTime * 0.01)) * 0.6 + skyNoise(vec2(ang * 19.0, 4.0)) * 0.4;
    col += uGlow * pow(sd, 3.0) * streak * uSunRays * (1.0 - clamp(uSunDir.y * 1.5, 0.0, 0.8));
  }

