    float az = atan(d.x, -d.z);
    float sunAz = atan(uSunDir.x, -uSunDir.z);
    float wP = smoothstep(0.28, 0.5, h), wC = 1.0 - wP;
    vec2 drift = vec2(uTime * 0.004, uTime * 0.0015);
    float dens = 0.0, shC = 0.0, shP = 0.0;
    if (wC > 0.001) {
      vec2 p = vec2(az * 4.0, h * uCloudVert) * uCloudScale * 2.2 + drift;
      float dA = sunAz - az; dA = dA - 6.2831853 * floor((dA + 3.1415927) / 6.2831853);
      vec2 ts = normalize(vec2(dA * 2.0, (uSunDir.y - h) * 4.0 + 0.0001)) * 0.2;
      float dc = cloudDensity(p);
      if (dc > 0.002) shC = cloudDensity(p + ts) * 0.4 + cloudDensity(p + ts * 2.6) * 0.35 + cloudDensity(p + ts * 5.5) * 0.25;
      dens += dc * wC;
    }
    if (wP > 0.001) {
      float t = uCloudAlt / (h + 0.22);
      vec2 p = d.xz * t * uCloudScale + drift;
      vec2 toSun = normalize(uSunDir.xz + 1e-4) * 0.16;
      float dp = cloudDensity(p);
