        float curtain = pow(ridge, mix(5.0, 9.0, step(0.5, uAuroraStyle))) * smoothstep(0.0, 0.35, skyFbm(p * 0.5 + 9.0));
        vec3 c = mix(uAuroraLow, mix(uAuroraMid, uAuroraTop, smoothstep(0.45, 1.0, fi)), smoothstep(0.0, 0.55, fi));
        a += c * curtain * (0.35 + 0.65 * (1.0 - fi)) / 10.0;
