  s += 0.7 * cos(dot(p, vec2(0.16, 0.99)) * 2.1 - t * 0.5) * vec2(0.16, 0.99);
  s += 0.45 * cos(dot(p, vec2(-0.3, 0.95)) * 3.7 - t * 0.6) * vec2(-0.3, 0.95);
